spec.data_model:
purchase_invoices: id; document_type string(16) default 'invoice' index; company_id FK companies restrict;
  supplier_id FK registries restrict; document_number string(30) nullable; document_date date index;
  payment_method_id FK payment_methods restrict; financial_account_id FK financial_accounts nullable nullOnDelete;
  cost_type_id FK cost_types nullable nullOnDelete; company_site_id FK company_sites nullable nullOnDelete;
  operational_site_id FK operational_sites nullable nullOnDelete; work_order_id FK work_orders nullable nullOnDelete;
  net_amount, vat_amount, total_amount decimal(15,2); notes text nullable; created_by FK users restrict; timestamps.
  Indici: (supplier_id, document_number), (document_type, document_date).
purchase_invoice_purchase_order: id; purchase_invoice_id FK cascadeOnDelete; purchase_order_id FK restrictOnDelete;
  timestamps; unique(purchase_invoice_id, purchase_order_id); index purchase_order_id.
purchase_invoice_installments: id; purchase_invoice_id FK cascadeOnDelete; sequence unsignedSmallInteger;
  due_date date index; amount decimal(15,2); payment_method_code string(32) nullable; paid_amount decimal(15,2)
  nullable; paid_at date nullable; financial_account_id FK financial_accounts nullable nullOnDelete;
  redistribution_snapshot json nullable; residual_amount VIRTUAL decimal(15,2); timestamps;
  unique(purchase_invoice_id, sequence); index (residual_amount, due_date).

endpoint.request:
{ paid_amount: number gt:0 max:installment.amount, paid_at: date, financial_account_id?: int|null
        (exists, company del documento o null), residual_mode: spread|new_installment (required se parziale),
        residual_due_date: date (required se new_installment, >= document_date) }

endpoint.errors:
403 senza purchase-invoices.pay; 409 "This installment is already paid: clear the payment first.";
        422 residual_mode "There are no later open installments to spread the residual on."; 422 financial_account_id
        "The account must belong to the document company."
